mapper.select:
select con.Con_Name as conName, con.Con_Code as conCode, con.Con_Money_Total as conMoneyTotal,
c1.C_Name_History as enbContractorNameHistory, c1.C_Name as enbContractorName, c1.C_Abbreviation as enbContrAbbName, c2.C_Name as enbSupervisorName, enis.Enis_Code as enisCode, enis.Enis_Sub_Code as enisSubCode, enis.Enis_Project_Name as enisProjectName, enis.Enis_Name as enisName, enis.Enis_Location as enisLocation, enis.Enis_Content_Summary as enisContentSummary, mn.* from Con_En_Budget mn left join Con_Contract con on con.Con_Id=mn.Con_Id
left join SYS_Company c1 on mn.Enb_Contractor_Id=c1.C_Id left join SYS_Company c2 on mn.Enb_Supervisor_Id=c2.C_Id left join Con_Enis enis on mn.Enis_Id=enis.Enis_Id ${params.authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Enb_Create_Time desc
limit #{params.start},#{params.size}
